/* Static cards remain readable without JavaScript; filters only change visibility. */
const boardSearch=document.getElementById('board-search'),boardMaker=document.getElementById('board-maker'),boardKind=document.getElementById('board-kind'),boardCards=[...document.querySelectorAll('.board-card')];
function filterScoreboards(){const term=boardSearch.value.trim().toLocaleLowerCase(),maker=boardMaker.value,kind=boardKind.value;let count=0;for(const card of boardCards){const board=['Fixed-digit board','Video / production','Hybrid display'].includes(card.dataset.kind),show=(!term||card.dataset.search.includes(term))&&(!maker||card.dataset.maker===maker)&&(kind==='all'||kind==='pictured'&&card.dataset.image==='true'||kind==='boards'&&board);card.hidden=!show;if(show)count++;}document.getElementById('board-count').textContent=count+' reference '+(count===1?'entry':'entries')+(count?' · Confirm the model in the timekeeper box before choosing a simulator.':' · No match. Try another model or maker, or use the arena finder.');}
boardSearch.addEventListener('input',filterScoreboards);boardMaker.addEventListener('change',filterScoreboards);boardKind.addEventListener('change',filterScoreboards);filterScoreboards();
